function screenHTML(o,kind){const title=kind==='title';return '<div class="screen-icon">'+(kind==='w'?'✦':kind==='l'?'↻':'✧')+'</div>'+(o.img?'<img alt="'+tr('Иллюстрация')+'" src="'+esc(o.img)+'">':'')+'<h2'+(title?' style="font-family:'+font(o.titleFont)+';font-size:'+o.titleSize+'px;color:'+o.titleColor+'"':'')+'>'+rich(o.title)+'</h2><p'+(title?' style="font-family:'+font(o.textFont)+';font-size:'+o.textSize+'px;color:'+o.textColor+'"':'')+'>'+rich(o.text)+'</p><button class="play" style="background:'+esc(o.btn?.startsWith('#')?o.btn:'#168568')+'">'+esc(kind==='title'?o.btn:o.label||tr('Переиграть'))+'</button>';}
function taskHTML(t,index=sel){if(!t)return '<h2>Добавьте задание</h2><p>Здесь появится его предпросмотр.</p>';let h='<span class="eyebrow">'+tr('ЗАДАНИЕ')+' '+(index+1)+'</span><h2 style="font-family:'+font(P.d.qFont)+';font-size:'+P.d.qSize+'px;color:'+P.d.qColor+'">'+rich(t.q)+'</h2>';if(['single','multiple','order'].includes(t.type)){h+='<p class="small">'+(t.type==='order'?tr('Нажмите варианты в правильном порядке'):t.type==='multiple'?tr('Выберите все правильные ответы'):tr('Выберите один ответ'))+'</p><div class="answers">';t.options.forEach((x,i)=>h+='<button data-a="'+(i+1)+'" style="font-family:'+font(P.d.aFont)+';font-size:'+P.d.aSize+'px;color:'+P.d.aColor+';background:'+P.d.aBg+'">'+rich(x)+'<span class="order-number"></span></button>');h+='</div>';}else if(t.type==='text')h+='<input class="text-answer" aria-label="'+tr('Ответ')+'" placeholder="'+tr('Введите ответ')+'" style="font-family:'+font(P.d.aFont)+';font-size:'+P.d.aSize+'px;color:'+P.d.aColor+';background:'+P.d.aBg+'"><div class="answer-preview" aria-live="polite"></div>';else h+='<p>'+tr('Ответьте на вопрос устно и нажмите «Готово».')+'</p>';return h+'<p class="feedback" role="status"></p><button class="check play" style="background:'+P.d.btnBg+'">'+(t.type==='oral'?tr('Готово'):tr('Проверить'))+'</button>';}
function renderPreview(){if(test)return;scene();position();hud();const overlay=el('editorOverlay');overlay.replaceChildren();overlay.classList.remove('show');const names={p0:'Игровой мир',p1:'Титульная страница',p2:'Герои',p3:'Мир и препятствия',p4:'Задание '+(sel+1),p5:'Оформление задания',p6:finalKind==='w'?'Экран победы':'Экран поражения',p7:'Жизни, таймер и баллы',p8:'Кнопки движения'};el('previewTitle').textContent=names[tab];if(['p1','p4','p5','p6'].includes(tab)){let card=document.createElement('div');card.className='editorPanel';card.dataset.object=tab==='p1'?'titleCard':tab==='p6'?(finalKind==='w'?'winCard':'loseCard'):'taskCard';if(tab==='p1'){card.innerHTML=screenHTML(P.ts,'title');titleStyle(card);card.querySelector('button').onclick=()=>start(true);}else if(tab==='p6'){let o=P.end[finalKind];card.innerHTML=screenHTML(o,finalKind);card.style.background=o.bg;card.style.color=o.color;card.querySelector('button').onclick=()=>start(true);}else{card.innerHTML=taskHTML(P.tasks[sel]);card.style.background=P.d.cardBg;if(P.tasks[sel])wireAnswer(card,P.tasks[sel],()=>{},true);}overlay.append(card);overlay.classList.add('show');}el('game').classList.toggle('screen-preview',overlay.classList.contains('show'));applyAppearance();applyGameLanguage();refreshObjectTools();markSelection();}
function fallbackImage(role){const shape=role==='bonus'?'<path fill="#ffcf48" stroke="#ca8a17" stroke-width="3" d="M50 6 63 34 94 38 71 59 77 91 50 76 23 91 29 59 6 38 37 34Z"/>':role==='ob'?'<path fill="#8a9da4" stroke="#556b76" stroke-width="3" d="m5 88 10-44 28-29 34 10 19 63Z"/><path fill="#b8c9cc" d="m15 44 28-29 8 31-23 22Z"/>':'<circle cx="50" cy="25" r="16" fill="#2b8a70"/><path fill="#2b8a70" d="M30 45h40v30H58v23H42V75H30Z"/>';return 'data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">'+shape+'</svg>');}
function spriteImage(role){const im=new Image();im.onerror=()=>{im.onerror=null;im.src=fallbackImage(role);};im.src=P.a[role];return im;}
function scene(){const bg=el('far');bg.style.backgroundImage='none';bg.replaceChildren();const u=P.a.bg||P.a.bf;for(let i=0;i<3;i++){const tile=document.createElement('div');tile.className='scenery-tile';tile.style.backgroundImage='url("'+u.replaceAll('"','%22')+'")';bg.append(tile);}el('mid').style.display=el('near').style.display='none';el('world').querySelectorAll('.dyn').forEach(x=>x.remove());for(const [id,size] of [['hero',P.heroSize],['enemy',P.enemySize]]){let im=spriteImage(id);im.id=id;im.dataset.object=id;im.className='sprite dyn';im.style.width=im.style.height=size+'px';el('world').append(im);}for(const [index,o] of P.obs.entries()){let im=spriteImage('ob');im.dataset.object='ob_'+index;im.dataset.index=index;im.className='ob dyn';im.dataset.x=o.x;im.style.width=o.w+'px';im.style.height=o.h+'px';el('world').append(im);}for(let i=0;i<P.bonusCount;i++){let im=spriteImage('bonus');im.className='bon dyn';im.dataset.object='bonus_'+i;im.dataset.x=bonusAt(i).x;im.dataset.task=i;im.style.width=im.style.height=P.bonusSize+'px';el('world').append(im);}}
function sceneryTiles(width,height,cam,speed){const w=Math.max(width,height*16/9),offset=cam*.22*speed,base=Math.floor(offset/w);return Array.from({length:3},(_,j)=>{const i=base+j;return{left:Math.floor(i*w-offset),width:Math.ceil(w)+1,flip:i%2?-1:1};});}
function heroTransform(){return 'scaleX('+((rt?.facing||1)*(P.heroFlip?-1:1))+') scaleY('+(hold.down?.6:1)+')';}
function position(){const r=rt||{x:P.starts.hero.x,y:P.starts.hero.y,enemyX:P.starts.enemy.x,enemyY:P.starts.enemy.y,cam:editorCam,col:{}};el('hero').style.left=r.x-r.cam+'px';el('hero').style.bottom=r.y+'px';el('hero').style.transform=heroTransform();el('enemy').style.left=r.enemyX-r.cam+'px';el('enemy').style.bottom=(r.enemyY||0)+'px';$$('.ob').forEach(o=>{const b=P.obs[+o.dataset.index];o.style.left=b.x-r.cam+'px';o.style.bottom=(b.y||0)+'px';});$$('.bon').forEach(b=>{const point=bonusAt(+b.dataset.task);b.style.left=point.x-r.cam+'px';b.style.bottom=point.y+'px';b.hidden=!!r.col[b.dataset.task];});const tiles=sceneryTiles(el('game').clientWidth,el('game').clientHeight,r.cam,P.par);el('far').querySelectorAll('.scenery-tile').forEach((tile,i)=>{tile.style.width=tiles[i].width+'px';tile.style.left=tiles[i].left+'px';tile.style.transform='scaleX('+tiles[i].flip+')';});}
function bonusY(){return Math.max(120,P.heroSize*.82+24);}
function hud(){const values={hLives:'♥ '+(rt?.lives??P.lives),hTime:P.timer?'◷ '+Math.max(0,Math.ceil(rt?.time??P.timer)):'◷ '+tr('Без таймера'),hBon:'★ '+Object.keys(rt?.col||{}).length+' / '+P.bonusCount};let update=false;for(const [key,value] of Object.entries(values))if(el(key).textContent!==value){el(key).textContent=value;update=true;}if(update)applyAppearance();}
function release(){hold.left=hold.right=hold.down=false;}
function hideModals(){for(const id of ['taskModal','endModal','titleScreen'])el(id).classList.remove('show');}
function start(skip=false){if(!P.tasks.length){notify('Добавьте хотя бы одно задание для запуска игры.');taskNotice('Добавьте задание для запуска игры.');return;}epoch++;cancelAnimationFrame(raf);release();test=true;el('game').classList.add('testing');el('game').classList.remove('screen-preview');el('editorOverlay').classList.remove('show');hideModals();rt={x:P.starts.hero.x,y:P.starts.hero.y,facing:1,vx:0,vy:0,enemyX:P.starts.enemy.x,enemyY:P.starts.enemy.y,enemyVy:0,enemyJumpVx:0,cam:editorCam,anchor:P.starts.hero.x-editorCam,col:{},lives:P.lives,time:P.timer,run:false,last:performance.now()};scene();position();applyAppearance();applyGameLanguage();hud();markSelection();if(P.ts.on&&!skip){el('titleCard').innerHTML=screenHTML(P.ts,'title');titleStyle(el('titleCard'));el('titleScreen').classList.add('show');applyCardPosition(el('titleCard'),'titleCard');el('titleCard').querySelector('button').onclick=()=>{hideModals();run();};}else run();}
function run(){if(!test)return;release();rt.run=true;rt.last=performance.now();cancelAnimationFrame(raf);raf=requestAnimationFrame(loop);}
function stopGame(){epoch++;cancelAnimationFrame(raf);test=false;rt=null;release();hideModals();el('game').classList.remove('testing');renderPreview();}
function jump(){if(test&&rt?.run&&grounded(rt.x,rt.y,P.heroSize,groundLevel('hero'))){rt.vy=760;beep(460);}}
function heroBox(x,y){return{x:x+P.heroSize*.18,y,w:P.heroSize*.62,h:P.heroSize*.82*(hold.down?.6:1)};}
function intersects(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;}
function step(dt){if(P.timer)rt.time-=dt;advanceEnemy(dt);const dx=Number(hold.right)-Number(hold.left),target=dx*(hold.down?130:285);if(dx)rt.facing=dx;rt.vx+=(target-rt.vx)*Math.min(1,dt*(dx?14:20));const moved=moveBody({x:rt.x,y:rt.y,vy:rt.vy},rt.vx,dt,P.heroSize,hold.down?.6:1,groundLevel('hero'));Object.assign(rt,moved);rt.cam=Math.max(0,rt.x-(rt.anchor??Math.min(260,el('game').clientWidth*.36)));for(let i=0;i<P.bonusCount;i++)if(!rt.col[i]&&intersects(heroBox(rt.x,rt.y),{...bonusAt(i),w:P.bonusSize,h:P.bonusSize})){openTask(i);return;}if(intersects(heroBox(rt.x,rt.y),bodyBox(rt.enemyX,rt.enemyY,P.enemySize))||P.timer>0&&rt.time<=0||rt.lives<=0)finish(false);}
function loop(now){if(!test||!rt?.run)return;let remaining=Math.min(.05,(now-rt.last)/1000);rt.last=now;while(remaining>0&&rt.run){const dt=Math.min(1/120,remaining);step(dt);remaining-=dt;}position();hud();if(rt.run)raf=requestAnimationFrame(loop);}
function wireAnswer(card,t,done,preview=false){let answers=[],locked=false;const feedback=card.querySelector('.feedback'),check=card.querySelector('.check');const input=card.querySelector('.text-answer'),inputPreview=card.querySelector('.answer-preview');if(input&&inputPreview)input.oninput=()=>inputPreview.innerHTML=rich(input.value);card.querySelectorAll('[data-a]').forEach(b=>b.onclick=()=>{if(locked)return;const v=b.dataset.a;if(t.type==='single')answers=[v];else answers=answers.includes(v)?answers.filter(x=>x!==v):[...answers,v];card.querySelectorAll('[data-a]').forEach(x=>{x.classList.toggle('selected',answers.includes(x.dataset.a));x.setAttribute('aria-pressed',answers.includes(x.dataset.a));x.querySelector('.order-number').textContent=t.type==='order'&&answers.includes(x.dataset.a)?answers.indexOf(x.dataset.a)+1:'';});});check.onclick=()=>{if(locked)return;const text=card.querySelector('.text-answer')?.value.trim()||'';if(t.type==='text'&&!text||['single','multiple','order'].includes(t.type)&&!answers.length){feedback.textContent=tr('Сначала укажите ответ.');return;}let expected=String(t.ok).split(',').map(x=>x.trim()).filter(Boolean),ok=t.type==='oral'||(t.type==='text'?(window.DogoniMath?window.DogoniMath.equal(text,t.ok):text.toLocaleLowerCase()===String(t.ok).trim().toLocaleLowerCase()):t.type==='order'?answers.join(',')===expected.join(','):answers.slice().sort().join(',')===expected.sort().join(','));feedback.innerHTML=(ok?tr('Верно! '):tr('Попробуйте ещё раз. '))+rich(t.fb||'');feedback.classList.toggle('incorrect',!ok);if(preview)return;locked=true;check.textContent=tr('Продолжить');check.onclick=()=>done(ok);};}
function openTask(i){rt.run=false;release();cancelAnimationFrame(raf);beep(780);let card=el('taskCard');card.style.background=P.d.cardBg;card.innerHTML=taskHTML(P.tasks[i],i);el('taskModal').classList.add('show');applyCardPosition(card,'taskCard');wireAnswer(card,P.tasks[i],ok=>{el('taskModal').classList.remove('show');if(ok)rt.col[i]=true;else{rt.lives--;rt.x=Math.max(0,bonusAt(i).x-P.heroSize-28);rt.y=groundLevel('hero');rt.vy=0;}position();hud();if(rt.lives<=0)return finish(false);if(Object.keys(rt.col).length===P.bonusCount)return finish(true);run();});}
function finish(win){rt.run=false;release();cancelAnimationFrame(raf);const o=P.end[win?'w':'l'];el('endCard').style.background=o.bg;el('endCard').style.color=o.color;el('endCard').innerHTML=screenHTML(o,win?'w':'l')+'<p class="result-stats">★ '+Object.keys(rt.col).length+' / '+P.bonusCount+' &nbsp; ♥ '+rt.lives+'</p><button class="secondary">'+tr('Начать заново')+'</button>';el('endCard').querySelector('.play').onclick=()=>start(true);el('endCard').querySelector('.secondary').onclick=()=>start(false);el('endModal').classList.add('show');applyCardPosition(el('endCard'),win?'winCard':'loseCard');}
function beep(hz){if(!P.sound||!P.vol)return;try{au=au||new(window.AudioContext||window.webkitAudioContext)();au.resume();let o=au.createOscillator(),g=au.createGain();o.connect(g);g.connect(au.destination);o.frequency.value=hz;g.gain.value=.08*P.vol;o.start();g.gain.exponentialRampToValueAtTime(.001,au.currentTime+.12);o.stop(au.currentTime+.12);}catch{}}
function controls(){const keys={ArrowLeft:'left',ArrowRight:'right',ArrowDown:'down',ArrowUp:'up',' ':'up'};document.addEventListener('keydown',e=>{if(!test||!rt?.run||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;const k=keys[e.key];if(!k)return;e.preventDefault();if(k==='up'){if(!e.repeat)jump();}else hold[k]=true;});document.addEventListener('keyup',e=>{if(keys[e.key])hold[keys[e.key]]=false;});window.addEventListener('blur',release);document.addEventListener('visibilitychange',()=>{release();if(rt)rt.last=performance.now();});$$('.controls button').forEach(b=>{b.onpointerdown=e=>{if(!test)return;e.preventDefault();b.setPointerCapture(e.pointerId);if(b.dataset.k==='up')jump();else hold[b.dataset.k]=true;};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>hold[b.dataset.k]=false;});window.addEventListener('resize',()=>{if(test){position();applyAppearance();el('game').querySelectorAll('[data-layout-key]').forEach(c=>applyCardPosition(c,c.dataset.layoutKey));}else renderPreview();});}
function download(text,name,type){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function bytes(s){return new TextEncoder().encode(s).length;}
function sizeLabel(n){return n<1024*1024?(n/1024).toFixed(1)+' КБ':(n/1024/1024).toFixed(2)+' МБ';}
function asDataURL(blob){return new Promise((res,rej)=>{const f=new FileReader();f.onload=()=>res(f.result);f.onerror=rej;f.readAsDataURL(blob);});}
async function optimizeImage(url,limit){
  // GIF and animated WebP stay intact. Only still PNG/JPEG images are recompressed.
  if(!/^data:image\/(png|jpeg|jpg);/i.test(url))return url;
  try{const im=await new Promise((res,rej)=>{const image=new Image();image.onload=()=>res(image);image.onerror=rej;image.src=url;});
    const scale=Math.min(1,limit/Math.max(im.naturalWidth,im.naturalHeight)),canvas=document.createElement('canvas');
    canvas.width=Math.max(1,Math.round(im.naturalWidth*scale));canvas.height=Math.max(1,Math.round(im.naturalHeight*scale));
    const ctx=canvas.getContext('2d');if(!ctx)return url;ctx.drawImage(im,0,0,canvas.width,canvas.height);
    const smaller=canvas.toDataURL('image/webp',.8);return smaller.length<url.length?smaller:url;
  }catch{return url;}
}
async function embeddedProject(compact){
  const project=JSON.parse(JSON.stringify(P));project.initialCamera=editorCam;
  // These source pictures are editor choices, not layers used by the game.
  project.a.bm=project.a.bn='';if(project.a.bg)project.a.bf='';
  const cache=new Map();
  for(const [obj,key,limit] of [...Object.keys(project.a).map(k=>[project.a,k,['bg','bf'].includes(k)?1440:512]),[project.ts,'img',800],[project.end.w,'img',800],[project.end.l,'img',800]]){
    const u=obj[key];if(!u)continue;
    const cacheKey=u+'|'+limit;
    if(!cache.has(cacheKey)){let data=u;if(!u.startsWith('data:')){try{const r=await fetch(u);if(!r.ok)throw Error();data=await asDataURL(await r.blob());}catch{if(obj===project.a&&['bonus','ob','hero','enemy'].includes(key))data=fallbackImage(key);else throw Error('Не удалось загрузить изображение для экспорта. Замените недоступную картинку.');}}
      cache.set(cacheKey,compact?await optimizeImage(data,limit):data);
    }obj[key]=cache.get(cacheKey);
  }return project;
}
async function packHTML(html){
  if(typeof CompressionStream==='undefined'||typeof DecompressionStream==='undefined')return html;
  try{const buffer=await new Response(new Blob([html]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer();
    let binary='';const data=new Uint8Array(buffer);for(let i=0;i<data.length;i+=8192)binary+=String.fromCharCode(...data.subarray(i,i+8192));
    const encoded=btoa(binary);
    const loader='(async()=>{try{const b=Uint8Array.from(atob('+JSON.stringify(encoded)+'),c=>c.charCodeAt(0));const h=await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream("gzip"))).text();document.open();document.write(h);document.close();}catch{document.body.textContent="Не удалось открыть сжатую игру. Используйте свежую версию браузера или обычный HTML.";}})();';
    const packed='<!doctype html><html lang="'+(P.language||'ru')+'"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(P.title)+'</title><body><p>Загружаем игру…</p><script>'+loader+'</script></body></html>';
    return bytes(packed)<bytes(html)?packed:html;
  }catch{return html;}
}
async function standalone(compact=false){
  const read=async url=>{const r=await fetch(url);if(!r.ok)throw Error('Не удалось загрузить файлы игры');return r.text();};
  const [css,appjs,mathjs,project]=await Promise.all([read('dogoni_app.css?v=7'),read('dogoni_app.js?v=7'),read('dogoni_math.js?v=7'),embeddedProject(compact)]);const js=mathjs+'\n'+appjs;
  const game=el('game').cloneNode(true);game.className='game';game.querySelectorAll('.dyn,.scenery-tile').forEach(x=>x.remove());
  for(const id of ['editorOverlay','taskCard','endCard','titleCard'])game.querySelector('#'+id).replaceChildren();
  game.querySelectorAll('.show').forEach(x=>x.classList.remove('show'));game.querySelectorAll('.object-selected').forEach(x=>x.classList.remove('object-selected'));
  const safe=s=>s.replace(/<\/script/gi,'<\\/script');
  const out='<!doctype html><html lang="'+(P.language||'ru')+'"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(P.title)+'</title><style>'+(compact?css.replace(/\/\*[\s\S]*?\*\//g,'').replace(/\s+/g,' ').replace(/\s*([{}:;,])\s*/g,'$1'):css)+'html,body{margin:0;width:100%;height:100%;overflow:hidden;background:transparent}.game-viewport{width:100vw;height:100dvh;aspect-ratio:auto;border-radius:0;box-shadow:none}.game{border-radius:0!important}.badge{display:none}</style><body><div class="game-viewport" id="gameViewport">'+game.outerHTML+'</div><script>window.DOGONI_PROJECT='+safe(JSON.stringify(project))+';</script><script>'+safe(js)+'</script></body></html>';
  return compact?packHTML(out):out;
}
function iframeCode(html){return '<iframe title="'+esc(P.title)+'" width="1200" height="675" style="display:block;width:100%;height:100%;aspect-ratio:16/9;border:0" srcdoc="'+esc(html)+'"></iframe>';}
async function exportGame(mode){
  if(!P.tasks.length){notify('Добавьте хотя бы одно задание перед экспортом.');return;}
  const error=P.tasks.map((t,i)=>validateTask(t)?'Задание '+(i+1)+': '+validateTask(t):'').find(Boolean);if(error){notify(error);return;}
  if(mode==='copy'&&preparedExport?.revision===revision){try{await navigator.clipboard.writeText(preparedExport.iframe);notify('Код для Genially скопирован'+(preparedExport.compact?' — облегчённая версия.':'.'));}catch{notify('Буфер обмена недоступен. Разрешите копирование в браузере или скачайте HTML.');}return;}
  const currentRevision=revision;const buttons=['miniBtn','htmlBtn','copyBtn'].map(el);buttons.forEach(b=>b.disabled=true);notify(mode==='mini'?'Уменьшаем изображения и сжимаем код…':'Подготавливаем игру…');
  try{
    if(mode==='mini'){
      const original=await standalone(false),compact=await standalone(true);if(revision!==currentRevision){notify('Проект изменился во время подготовки. Нажмите «Облегчить код» ещё раз.');return;}
      const before=bytes(iframeCode(original));const best=bytes(iframeCode(compact))<before?compact:original;const iframe=iframeCode(best),after=bytes(iframe);
      preparedExport={revision,html:best,iframe,compact:true};el('miniBtn').setAttribute('aria-pressed','true');el('exportStatus').textContent='Код для Genially: '+sizeLabel(before)+' → '+sizeLabel(after)+' (−'+Math.round((1-after/before)*100)+'%). GIF сохранены с анимацией.';
      notify('Готово. Нажмите «Копировать для Genially».');
    }else{
      const html=preparedExport?.revision===revision?preparedExport.html:await standalone(false);
      if(revision!==currentRevision){notify('Проект изменился. Повторите экспорт.');return;}
      if(mode==='copy'){preparedExport={revision,html,iframe:iframeCode(html),compact:false};try{await navigator.clipboard.writeText(preparedExport.iframe);notify('Код для Genially скопирован.');}catch{notify('Код подготовлен. Нажмите «Копировать для Genially» ещё раз.');}}
      else{download(html,preparedExport?.compact?'dogoni-compact.html':'dogoni-game.html','text/html');notify('Игра сохранена в HTML');}
    }
  }catch(e){notify('Экспорт не завершён: '+e.message);}finally{buttons.forEach(b=>b.disabled=false);}
}

function normalizeScene(n,p,d){
 n.starts={};for(const k of ['hero','enemy'])n.starts[k]={x:clamp(p.starts?.[k]?.x??d.starts[k].x,0,20000,d.starts[k].x),y:clamp(p.starts?.[k]?.y??0,0,4000,0)};
 n.bonuses=Array.isArray(p.bonuses)?p.bonuses.map((b,i)=>({x:clamp(b?.x,0,20000,480+i*360),y:b?.y==null?null:clamp(b.y,0,4000,120)})):[];
 n.uiPositions={};for(const k of ['hLives','hTime','hBon','controls','titleCard','winCard','loseCard','taskCard'])if(p.uiPositions?.[k])n.uiPositions[k]={x:clamp(p.uiPositions[k].x,0,1,0),y:clamp(p.uiPositions[k].y,0,1,0)};
 const color=(v,f)=>/^#[0-9a-f]{6}$/i.test(v)?v:f;
 n.hudStyle={};for(const k of ['hLives','hTime','hBon'])n.hudStyle[k]={scale:clamp(p.hudStyle?.[k]?.scale??100,60,180,100),bg:color(p.hudStyle?.[k]?.bg,d.hudStyle[k].bg),color:color(p.hudStyle?.[k]?.color,d.hudStyle[k].color)};
 n.controlStyle={...d.controlStyle,...p.controlStyle};for(const k of ['bg','color','jumpBg','jumpColor'])n.controlStyle[k]=color(n.controlStyle[k],d.controlStyle[k]);n.controlStyle.size=clamp(n.controlStyle.size,28,64,35);if(!['circle','rounded','square'].includes(n.controlStyle.shape))n.controlStyle.shape='circle';
}
function fillSceneSettings(){
 for(const [name,key] of [['Lives','hLives'],['Time','hTime'],['Score','hBon']])for(const [suffix,k] of [['Scale','scale'],['Bg','bg'],['Color','color']])bind('hud'+name+suffix,()=>P.hudStyle[key][k],v=>P.hudStyle[key][k]=k==='scale'?+v:v);
 for(const [suffix,k] of [['Shape','shape'],['Size','size'],['Bg','bg'],['Color','color'],['JumpBg','jumpBg'],['JumpColor','jumpColor']])bind('control'+suffix,()=>P.controlStyle[k],v=>P.controlStyle[k]=k==='size'?+v:v);
}
function bonusAt(i){const b=P.bonuses?.[i];return{x:b?.x??480+i*360,y:b?.y??bonusY()};}
function bodyBox(x,y,size,scale=1){return{x:x+size*.18,y,w:size*.62,h:size*.82*scale};}
function groundLevel(role){return P.starts?.[role]?.y||0;}
function grounded(x,y,size,floor=0){const b=bodyBox(x,y,size);return y<=floor+.1||P.obs.some(o=>Math.abs(y-((o.y||0)+o.h))<.5&&b.x+b.w>o.x&&b.x<o.x+o.w);}
function moveBody(body,vx,dt,size,scale=1,floor=0){
 const oldY=body.y,old=bodyBox(body.x,oldY,size,scale);let vy=body.vy-1550*dt,y=Math.max(floor,oldY+vy*dt),x=Math.max(0,body.x+vx*dt);if(y===floor)vy=0;
 for(const o of P.obs){const obstacle={x:o.x,y:o.y||0,w:o.w,h:o.h};let b=bodyBox(x,y,size,scale);if(!intersects(b,obstacle))continue;const top=obstacle.y+o.h;
  if(oldY>=top-.1&&vy<=0){y=top;vy=0;}
  else if(old.y+old.h<=obstacle.y+.1&&vy>0){y=Math.max(floor,obstacle.y-b.h);vy=0;}
  else if(vx!==0){x=vx>0?o.x-size*.8:o.x+o.w-size*.18;}
 }
 return{x:Math.max(0,x),y,vy};
}
function enemyJumpPlan(o){const y=rt.enemyY||0,body=bodyBox(rt.enemyX,y,P.enemySize),height=(o.y||0)+o.h-y;if(height<=0||(o.y||0)>y+body.h)return null;
 const base=P.enemySpeed*26,v=Math.sqrt(2*1550*Math.max(160,height+60)),root=Math.sqrt(v*v-2*1550*height),up=(v-root)/1550,down=(v+root)/1550;
 const speed=Math.max(base,(o.w+body.w+28)/(down-up));return{vy:v,speed,trigger:speed*up+12};
}
function advanceEnemy(dt){
 rt.enemyY??=groundLevel('enemy');rt.enemyVy??=0;rt.enemyJumpVx??=0;
 if(grounded(rt.enemyX,rt.enemyY,P.enemySize,groundLevel('enemy'))&&rt.enemyVy<=0){rt.enemyJumpVx=0;const body=bodyBox(rt.enemyX,rt.enemyY,P.enemySize);
  for(const o of P.obs.slice().sort((a,b)=>a.x-b.x)){if(o.x+o.w<=body.x)continue;const plan=enemyJumpPlan(o);if(plan&&o.x-body.x-body.w<=plan.trigger){rt.enemyVy=plan.vy;rt.enemyJumpVx=plan.speed;break;}}
 }
 const m=moveBody({x:rt.enemyX,y:rt.enemyY,vy:rt.enemyVy},rt.enemyJumpVx||P.enemySpeed*26,dt,P.enemySize,1,groundLevel('enemy'));rt.enemyX=m.x;rt.enemyY=m.y;rt.enemyVy=m.vy;
}
function applyCardPosition(card,key){if(!card)return;card.dataset.layoutKey=key;const p=P.uiPositions[key];if(p){card.style.position='absolute';card.style.margin='0';card.style.left=p.x*Math.max(0,el('game').clientWidth-card.offsetWidth)+'px';card.style.top=p.y*Math.max(0,el('game').clientHeight-card.offsetHeight)+'px';}else{card.style.position='';card.style.margin='';card.style.left='';card.style.top='';}}
function applyAppearance(){
 const w=el('game').clientWidth,h=el('game').clientHeight;
 for(const [index,key] of ['hLives','hTime','hBon'].entries()){const e=el(key),s=P.hudStyle[key],scale=s.scale/100;e.style.background=s.bg;e.style.color=s.color;e.style.fontSize=12*scale+'px';e.style.padding=7*scale+'px '+11*scale+'px';e.style.borderRadius=18*scale+'px';
  const p=P.uiPositions[key];e.style.left=(p?p.x*Math.max(0,w-e.offsetWidth):index===0?12:index===1?(w-e.offsetWidth)/2:w-e.offsetWidth-12)+'px';e.style.top=(p?p.y*Math.max(0,h-e.offsetHeight):12)+'px';
 }
 const controls=el('movementControls'),s=P.controlStyle;controls.querySelectorAll('button').forEach(b=>{const jump=b.dataset.k==='up';b.style.background=jump?s.jumpBg:s.bg;b.style.color=jump?s.jumpColor:s.color;b.style.borderRadius=s.shape==='circle'?'50%':s.shape==='rounded'?'12px':'2px';b.style.width=b.style.height=s.size+'px';b.style.fontSize=Math.round(s.size*.53)+'px';});
 const p=P.uiPositions.controls;controls.style.left=p?p.x*Math.max(0,w-controls.offsetWidth)+'px':'auto';controls.style.top=p?p.y*Math.max(0,h-controls.offsetHeight)+'px':'auto';controls.style.right=p?'auto':'12px';controls.style.bottom=p?'auto':'12px';
 if(!test)el('editorOverlay').querySelectorAll('[data-object]').forEach(c=>applyCardPosition(c,c.dataset.object));
}
function objectNames(){const items=[['hero','Герой'],['enemy','Противник'],...P.bonuses.map((_,i)=>['bonus_'+i,'Бонус '+(i+1)]),...P.obs.map((_,i)=>['ob_'+i,'Препятствие '+(i+1)]),['hLives','Жизни'],['hTime','Таймер'],['hBon','Баллы'],['controls','Кнопки движения']];if(tab==='p1')items.push(['titleCard','Титульная карточка']);if(tab==='p4'||tab==='p5')items.push(['taskCard','Карточка задания']);if(tab==='p6')items.push([finalKind==='w'?'winCard':'loseCard','Карточка финала']);return items;}
function isWorldObject(key){return key==='hero'||key==='enemy'||/^(bonus|ob)_\d+$/.test(key);}
function worldPoint(key){if(key==='hero'||key==='enemy')return {...P.starts[key]};const i=+key.split('_')[1];return key.startsWith('bonus_')?bonusAt(i):P.obs[i]?{x:P.obs[i].x,y:P.obs[i].y||0}:null;}
function objectSize(key){if(key==='hero')return{w:P.heroSize,h:P.heroSize};if(key==='enemy')return{w:P.enemySize,h:P.enemySize};if(key.startsWith('bonus_'))return{w:P.bonusSize,h:P.bonusSize};const o=P.obs[+key.split('_')[1]];return{w:o?.w||78,h:o?.h||72};}
function setWorldPoint(key,p){if(key==='hero'||key==='enemy')P.starts[key]={...p};else if(key.startsWith('bonus_'))P.bonuses[+key.split('_')[1]]={...p};else Object.assign(P.obs[+key.split('_')[1]],p);}
function clampWorldPoint(key,p){const size=objectSize(key),w=el('game').clientWidth,h=el('game').clientHeight;return{x:clamp(p.x,editorCam,editorCam+Math.max(0,w-size.w),editorCam),y:clamp(p.y,0,Math.max(0,h-size.h),0)};}
function markSelection(){el('game').querySelectorAll('[data-object]').forEach(e=>{e.classList.toggle('object-selected',!test&&e.dataset.object===selectedObject);e.tabIndex=test?-1:0;});if(el('selectionInfo'))el('selectionInfo').textContent=selectedObject?'Выбран: '+(objectNames().find(([k])=>k===selectedObject)?.[1]||selectedObject)+'. Перетащите рамку или используйте стрелки.':'Нажмите объект и перетащите зелёную пунктирную рамку. Стрелки — сдвиг; Shift — шаг 10.';}
function refreshObjectTools(){const select=el('objectSelect');if(!select)return;select.innerHTML='<option value="">Выберите объект</option>'+objectNames().map(([k,n])=>'<option value="'+k+'">'+n+'</option>').join('');select.value=selectedObject;el('resetObject').disabled=!selectedObject;const last=Math.max(el('game').clientWidth,...P.obs.map(o=>o.x+o.w),...P.bonuses.map(b=>b.x+P.bonusSize));el('sceneScroll').max=Math.max(0,last-el('game').clientWidth+160);el('sceneScroll').value=editorCam;el('sceneScroll').disabled=!['p0','p2','p3','p7','p8'].includes(tab);}
function selectObject(key,reveal=false){selectedObject=key;if(reveal&&isWorldObject(key)){if(!['p0','p2','p3','p7','p8'].includes(tab))navigateWorld();const p=worldPoint(key);if(p)editorCam=Math.max(0,p.x-el('game').clientWidth*.45);invalidateExport();position();}refreshObjectTools();markSelection();}
function navigateWorld(){tab='p3';$$('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$$('.pane').forEach(p=>p.classList.toggle('active',p.id===tab));renderPreview();}
function commitObjectMove(){changed();markSelection();}
function editorInteractions(){
 const game=el('game');
 el('objectSelect').onchange=e=>{if(test)stopGame();const key=e.target.value;if((isWorldObject(key)||['hLives','hTime','hBon','controls'].includes(key))&&!['p0','p2','p3','p7','p8'].includes(tab))navigateWorld();selectObject(key,true);};
 el('sceneScroll').oninput=e=>{editorCam=+e.target.value;invalidateExport();position();};
 el('resetObject').onclick=()=>{if(!selectedObject)return;const key=selectedObject;if(key==='hero'||key==='enemy')P.starts[key]={...def().starts[key]};else if(key.startsWith('bonus_'))P.bonuses[+key.split('_')[1]]={x:480+(+key.split('_')[1])*360,y:null};else if(key.startsWith('ob_'))Object.assign(P.obs[+key.split('_')[1]],{x:420+(+key.split('_')[1])*360,y:0});else delete P.uiPositions[key];commitObjectMove();selectObject(key,true);};
 game.addEventListener('pointerdown',e=>{if(test||e.button>0)return;const node=e.target.closest('[data-object]');if(!node){selectObject('');return;}const key=node.dataset.object;if(e.target.closest('input,textarea,select,button')&&key!=='controls')return;e.preventDefault();selectObject(key);const rect=node.getBoundingClientRect(),bounds=game.getBoundingClientRect(),scale=stageScale();dragState={id:e.pointerId,key,node,startX:e.clientX,startY:e.clientY,point:isWorldObject(key)?worldPoint(key):{x:(rect.left-bounds.left)/scale,y:(rect.top-bounds.top)/scale},oldUI:P.uiPositions[key]?{...P.uiPositions[key]}:null,width:rect.width/scale,height:rect.height/scale};game.setPointerCapture(e.pointerId);});
 game.addEventListener('pointermove',e=>{if(!dragState||e.pointerId!==dragState.id)return;const d=dragState,dx=(e.clientX-d.startX)/stageScale(),dy=(e.clientY-d.startY)/stageScale();if(isWorldObject(d.key)){setWorldPoint(d.key,clampWorldPoint(d.key,{x:d.point.x+dx,y:d.point.y-dy}));position();}else{const w=Math.max(1,game.clientWidth-d.width),h=Math.max(1,game.clientHeight-d.height);P.uiPositions[d.key]={x:clamp((d.point.x+dx)/w,0,1,0),y:clamp((d.point.y+dy)/h,0,1,0)};applyAppearance();}markSelection();});
 const finish=e=>{if(!dragState||e.pointerId!==dragState.id)return;const d=dragState;dragState=null;if(e.type==='pointercancel'){if(isWorldObject(d.key))setWorldPoint(d.key,d.point);else if(d.oldUI)P.uiPositions[d.key]=d.oldUI;else delete P.uiPositions[d.key];renderPreview();}else commitObjectMove();if(game.hasPointerCapture(e.pointerId))game.releasePointerCapture(e.pointerId);};game.addEventListener('pointerup',finish);game.addEventListener('pointercancel',finish);game.addEventListener('lostpointercapture',finish);
 document.addEventListener('keydown',e=>{if(test||dragState||!selectedObject||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.key==='Escape'){selectObject('');return;}const delta={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];if(!delta)return;e.preventDefault();const n=e.shiftKey?10:1;if(isWorldObject(selectedObject)){const p=worldPoint(selectedObject);setWorldPoint(selectedObject,clampWorldPoint(selectedObject,{x:p.x+delta[0]*n,y:p.y-delta[1]*n}));}else{const node=[...game.querySelectorAll('[data-object]')].find(x=>x.dataset.object===selectedObject);if(!node)return;const r=node.getBoundingClientRect(),b=game.getBoundingClientRect();P.uiPositions[selectedObject]={x:clamp(((r.left-b.left)/stageScale()+delta[0]*n)/Math.max(1,game.clientWidth-node.offsetWidth),0,1,0),y:clamp(((r.top-b.top)/stageScale()+delta[1]*n)/Math.max(1,game.clientHeight-node.offsetHeight),0,1,0)};}commitObjectMove();});
}

function events(){historyEvents();controls();editorInteractions();$$('.tabs button').forEach(b=>b.onclick=()=>{if(test)stopGame();tab=b.dataset.tab;$$('.tabs button').forEach(x=>x.classList.toggle('active',x===b));$$('.pane').forEach(x=>x.classList.toggle('active',x.id===tab));renderPreview();});for(const id of ['taskType','taskQ','taskOpt','taskOk','taskFb'])el(id).oninput=()=>{saveTask();if(id==='taskType')fillTask();};el('saveTask').onclick=()=>saveTask(true);el('addTask').onclick=addTask;el('delTask').onclick=deleteTask;el('previewWin').onclick=()=>{finalKind='w';renderPreview();};el('previewLose').onclick=()=>{finalKind='l';renderPreview();};el('testBtn').onclick=()=>start();el('stop').onclick=stopGame;el('saveBtn').onclick=()=>{saveTask();persist();download(JSON.stringify(P,null,2),'dogoni-project.json','application/json');};el('loadBtn').onclick=()=>el('loadFile').click();el('loadFile').onchange=async e=>{try{if(!e.target.files[0])return;P=normalize(JSON.parse(await e.target.files[0].text()));invalidateExport();syncTasks();recordHistory();stopGame();fill();assets();await persist();notify('Проект загружен');}catch{notify('Не удалось загрузить проект. Выберите JSON-файл редактора.');}e.target.value='';};el('htmlBtn').onclick=()=>exportGame('html');el('miniBtn').onclick=()=>exportGame('mini');el('copyBtn').onclick=()=>exportGame('copy');el('cont').onclick=()=>{el('resume').classList.remove('show');notify('Продолжаем редактирование');};el('startNew').onclick=async()=>{P=def();invalidateExport();sel=0;editorCam=0;selectedObject='';syncTasks();recordHistory();fill();assets();el('resume').classList.remove('show');await persist();};window.addEventListener('pagehide',()=>{if(!embedded)persist();});}
async function init(){if(embedded){P=normalize(embedded);editorCam=clamp(P.initialCamera??0,0,20000,0);syncTasks();setupStage();controls();start();return;}db=await openDB();stored=await dbGet();if(!stored)try{stored=JSON.parse(localStorage.getItem('dogoniProject'));}catch{}if(stored)try{P=normalize(stored);}catch{notify('Сохранённый проект повреждён. Загружены исходные настройки.');stored=null;}syncTasks();setupStage();resetHistory();fill();assets();events();if(stored)el('resume').classList.add('show');else await persist();}
